#ifndef TRNG_H
#define TRNG_H
#include<stdint.h>

/**
 * @fn uint32_t TRNG_Generate(void *output, int req_sec_strength, int no_of_bytes) 
 * @details The function TRNG_Generate generates random numbers using a True Random Number Generator (TRNG)
 * based on NIST standards.
 * @param output is a pointer to the memory location where the generated random bytes will be stored.
 * @param req_sec_strength represents the required security strength for the random number generation process. 
 * It is used to specify the level of security that the generated random numbers should possess.
 * @param no_of_bytes represents the number of bytes of random data that you want to generate using the True Random Number Generator (TRNG).
 * @return an integer value. If the function executes successfully, it will return 0. If there are any errors during the TRNG generation process,
 *  it will return the corresponding error code.
 */
uint32_t TRNG_Generate(void * output,int req_sec_strength,int no_of_bytes);

/**
 * @fn uint8_t rand() 
 * @details The function generates a random 8-bit value using a True Random Number Generator (TRNG) and
 * logs any errors encountered during the process.
 * @return a random 8-bit unsigned integer value generated by the TRNG_Generate function.
 */
uint8_t Rand();
#endif